entries[215369] = { ["name"] = "Pattern: Invoker's Cord", ["text"] = "Requires Tailoring (150)\n\nUse: Teaches you how to sew Invoker's Cord.\nSell Price:\nInvoker's Cord\nBinds when equipped\nWaist Cloth\n24 Armor\n+5 Intellect\nDurability 25 / 25\nRequires Level 25\nEquip: Increases damage and healing done by magical spells and effects by up to 7.\nSell Price:\nRequires Bolt of Silk Cloth (3), Shadowgem , Fine Thread , Gray Dye" }
