entries[215373] = { ["name"] = "Silver Hand Training Hammer", ["text"] = "Two-Hand Mace\n53 - 81 Damage Speed 3.40\n(19.71 damage per second)\nDurability 65 / 65\nRequires Level 26\n\"Recovered from Theramore Isle where its owner was slain in battle against bloodthirsty orcish hordes.\"\nSell Price:" }
entries[215374] = { ["name"] = "Ancestral Sword", ["text"] = "Two-Hand Sword\n17 - 46 Damage Speed 3.10\n(10.16 damage per second)\nDurability 65 / 65\nRequires Level 26\n\"Passed down by a noble Lordaeron family. Once thought to be lost in the swamps around Kyross along with the last warrior to wield it.\"\nSell Price:" }
entries[215375] = { ["name"] = "Tactician's Staff", ["text"] = "Two-Hand Staff\n16 - 49 Damage Speed 3.50\n(9.29 damage per second)\nDurability 65 / 65\nRequires Level 26\n\"Its owner's keen grasp of battlefield tactics was matched only by her fearsome command of frost and flame.\"\nSell Price:" }
entries[215376] = { ["name"] = "Crusader's Mace", ["text"] = "Main Hand Mace\n21 - 36 Damage Speed 2.90\n(9.83 damage per second)\nDurability 65 / 65\nRequires Level 26\n\"Flecked with dried bits of insect carapace.\"\nSell Price:" }
entries[215383] = { ["name"] = "Plans: Reflective Truesilver Braincage", ["text"] = "Binds when picked up\nRequires Blacksmithing (225)\n\nUse: Teaches you how to make a Reflective Truesilver Braincage.\nSell Price:\nReflective Truesilver Braincage\nBinds when picked up\nHead Plate\n426 Armor\n+14 Stamina\n+15 Intellect\nDurability 100 / 100\nRequires Level 40\nRequires Blacksmithing (225)\nEquip: Increases damage and healing done by magical spells and effects by up to 21.\n\nUse: Gain reinforced willpower, preventing Silence, Interrupt effects, and spell pushback for 10 sec. (10 Min Cooldown)\nSell Price:\nRequires Mithril Bar (25), Low-Background Truesilver Plates (4), Hyperconductive Arcano-Filament (2), Polished Truesilver Gears" }
