entries[215429] = { ["name"] = "Schematic: Polished Truesilver Gears", ["text"] = "Binds when picked up\nRequires Engineering (200)\n\nUse: Teaches you how to make a set of Polished Truesilver Gears.\nSell Price:\nPolished Truesilver Gears\nRequires Truesilver Bar , Pile of Tarnished Gears (5)" }
