entries[215456] = { ["name"] = "Singed Message", ["text"] = "\"Told you so.\"" }
entries[215458] = { ["name"] = "Enclosed Message", ["text"] = "Classes: Rogue\n\"Seriously, DO NOT try to open the final box. You already got what you wanted.\"" }
