entries[220164] = { ["name"] = "Rune of the Gladiator", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your boots with the Gladiator Stance rune:\n\nAn aggressive stance that increases damage while you are wearing a shield by 10% and increases block chance by 10%, but reduces armor by 30% and threat generated by 30%. In addition, you gain 50% increased Rage when your auto-attack damages an enemy not targeting you.\n\nWhile wearing a shield in Gladiator Stance, you may use all abilities that are restricted to other stances.\n\"Teaches you a new Engraving ability.\"" }
entries[220165] = { ["name"] = "Rune of Wrath", ["text"] = "Binds when picked up\nUnique\nClasses: Paladin\nEngrave your helm with the Wrath rune:\n\nYour Consecration damage can now be critical strikes, and damage from your Exorcism, Holy Shock, Sunlight, Holy Wrath, and Consecration spells gains additional critical strike chance equal to your melee critical strike chance.\n\"Teaches you a new Engraving ability.\"" }
entries[220166] = { ["name"] = "Fiery Infernal Core", ["text"] = "Quest Item" }
entries[220167] = { ["name"] = "Shimmering Grave Dust", ["text"] = "Quest Item\n\"Grave dust from the resting place of one murdered by those most loved...\"" }
entries[220168] = { ["name"] = "Triple-Brewed Molten Lager", ["text"] = "Quest Item\nUnique\n\"An elixir of fire, created with steady hands and an unsteady mind...\"" }
entries[220169] = { ["name"] = "Symbol of Faith", ["text"] = "Quest Item\n\"A symbol of faith, gifted from one with newly discovered purpose...\"" }
entries[220213] = { ["name"] = "Fel Lifeblood", ["text"] = "Binds when picked up\nUnique" }
entries[220214] = { ["name"] = "Infernal Chain Link", ["text"] = "Binds when picked up\nUnique (5)" }
entries[220216] = { ["name"] = "Infernal Lasso", ["text"] = "Binds when picked up\nUse: Weaken Calefactus the Unleashed. (30 Sec Cooldown)" }
entries[220217] = { ["name"] = "Rune of the Ravenous", ["text"] = "Binds when picked up\nClasses: Hunter\nEngrave your helm with the Rapid Killing rune:\n\nReduces the cooldown on Rapid Fire by 80%, Rapid Fire now also grants 40% increased melee attack speed, and your next Shot ability within 20 sec after killing a target worth experience or honor deals 20% increased damage.\n\"Teaches you a new Engraving ability.\"" }
entries[220345] = { ["name"] = "Sanguine Sorcery", ["text"] = "Binds when picked up\nUnique\n\"Outlines a variety of powerful blood rituals. A controversial addition to any library's collection.\"" }
entries[220346] = { ["name"] = "Legends of the Tidesages", ["text"] = "Binds when picked up\nUnique\n\"Covered in illegible notes and diagrams scrawled by an unsteady hand. It could still be a decent addition to any library's collection.\"" }
entries[220347] = { ["name"] = "The Liminal and the Arcane", ["text"] = "Binds when picked up\nUnique\n\"The words swim on the page, defying attempts to read them. A puzzling addition to any library's collection.\"" }
entries[220348] = { ["name"] = "Everyday Etiquette", ["text"] = "Binds when picked up\nUnique\n\"A guide to the role of elementary magic in polite Highborne society. A fine addition to any library's collection.\"" }
entries[220349] = { ["name"] = "Stonewrought Design", ["text"] = "Binds when picked up\nUnique\n\"Sturdy architectural techniques capable of withstanding all but the most cataclysmic disasters. A fine addition to any library's collection.\"" }
entries[220350] = { ["name"] = "Venomous Journeys", ["text"] = "Binds when picked up\nUnique\n\"Notes on the mind-altering properties of various toxins and venoms. A fine addition to any library's collection.\"" }
entries[220351] = { ["name"] = "Murky Air Sapta", ["text"] = "Binds when picked up\nUnique\nUse: Allows the shaman to see elemental spirits." }
entries[220352] = { ["name"] = "A Mind of Metal", ["text"] = "Binds when picked up\nUnique\n\"Dwarven techniques for applying magic to metallurgy, strip-mining and heavy industry. An informative, if bleak, addition to any library's collection.\"" }
entries[220353] = { ["name"] = "Conjurer's Codex", ["text"] = "Binds when picked up\nUnique\n\"A pre-war collection of spells and arcane theories that have largely fallen out of modern use. A fine addition to any library's collection.\"" }
entries[220360] = { ["name"] = "Rune of Efflorescence", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your bracers with the Efflorescence rune:\n\nYour Swiftmend now also causes Efflorescence, healing all party members within 15 yards of the Swiftmend target's location for [source value] every 1 sec for 15 sec.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[220375] = { ["name"] = "Fragment of Air", ["text"] = "Binds when picked up\nUnique\nUse: Combine the Fragment of Air with Elemental Essences. May help with finding the corrupted shrine." }
entries[220446] = { ["name"] = "Otherworldly Treasure", ["text"] = "Binds when picked up\n<Right Click to Open>" }
entries[220510] = { ["name"] = "Elemental Essence", ["text"] = "Quest Item\nClasses: Shaman" }
entries[220525] = { ["name"] = "Glowing Fragment of Air", ["text"] = "Binds when picked up\nUnique" }
entries[220606] = { ["name"] = "Idol of the Dream", ["text"] = "Binds when picked up\nUnique\nRelic Idol\nRequires Level 50\nEquip: Increases the damage of Swipe and Shred by 2%.\nSell Price:" }
entries[220610] = { ["name"] = "Rune of Mental Dexterity", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your helm with the Mental Dexterity rune:\n\nDealing damage with Stormstrike increases your Attack Power by 150% of your Intellect, and your spell damage by 35% of your total Attack Power for 30 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[220612] = { ["name"] = "Rune of Tidal Waves", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your helm with the Tidal Waves rune:\n\nWhen you cast Chain Heal or Riptide you gain 2 charges of Tidal Waves, which reduces the cast time of your Healing Wave by 30%, reduces the cast time of your Chain Heal by 15%, and increases the critical effect chance of your Lesser Healing Wave by 25%.\n\"Teaches you a new Engraving ability.\"" }
entries[220613] = { ["name"] = "Rune of Rolling Thunder", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your bracers with the Rolling Thunder rune:\n\nLightning Bolt and Chain Lightning have a 50% chance to add an additional charge to your active Lightning Shield, up to a maximum of 9 Charges.\n\nEarth Shock now releases all Lightning Shield charges above 3, dealing their damage to the target, and energizing you for 2% of your maximum mana per charge released.\n\"Teaches you a new Engraving ability.\"" }
entries[220614] = { ["name"] = "Rune of Static Shock", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your bracers with the Static Shock rune:\n\nYour Lightning Shield now has 9 charges, and your melee attacks have a 12% chance (6% chance while dual - wielding) to trigger one of those charges, immediately damaging your target.\n\"Teaches you a new Engraving ability.\"" }
entries[220616] = { ["name"] = "Rune of Overcharged", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your bracers with the Overcharged rune:\n\nYour Lightning Shield never loses charges, now has a 3 sec cooldown, and deals damage to all enemies within 8 yards.\n\"Teaches you a new Engraving ability.\"" }
entries[220617] = { ["name"] = "Rune of Pandemic", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your helm with the Pandemic rune:\n\nPeriodic damage from your Corruption, Unstable Affliction, Curse of Agony, Immolate, Curse of Doom, and Siphon Life abilities can now be critical strikes.\n\"Teaches you a new Engraving ability.\"" }
entries[220618] = { ["name"] = "Rune of Immolation Aura", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your bracers with the Immolation Aura rune:\n\nBurns nearby enemies for [source value] damage every time an enemy makes a melee attack against you (no more than once per sec), reduces all magic damage taken by 10%, and increases Fire damage done by 10%. Lasts until cancelled.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[220682] = { ["name"] = "Rune of the Unbridled", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your bracers with the Rampage rune:\n\nGo on a rampage, increasing your attack power by 15% for 30 sec. This ability can only be used while Enraged.\n\"Teaches you a new Engraving ability.\"" }
entries[220687] = { ["name"] = "Rune of the Raptor", ["text"] = "Binds when picked up\nClasses: Hunter\nEngrave your bracers with the Raptor Fury rune:\n\nRaptor Strike increases damage done by Raptor Strike and Mongoose Bite by 15% for 30 sec, stacking up to 5 times. Subsequent doses do not extend the duration of this effect.\n\"Teaches you a new Engraving ability.\"" }
entries[220754] = { ["name"] = "Rune of the Windstorm", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your helm with the Gale Winds rune:\n\nIncreases the damage done by your Hurricane by 100%, it no longer has a cooldown, and its mana cost is reduced by 60%.\n\"Teaches you a new Engraving ability.\"" }
entries[220775] = { ["name"] = "Engineering Exchange Ticket", ["text"] = "Binds when picked up\n\"It just says 'I.O.U' with a smiley face next to it.\"" }
entries[220791] = { ["name"] = "Rune of the Jungle Cat", ["text"] = "Binds when picked up\nClasses: Hunter\nEngrave your helm with the Catlike Reflexes rune:\n\nIncreases your chance to dodge by 20% and your pet's chance to dodge by 9%. In addition, reduces the cooldown of your Flanking Strike ability by 50%.\n\"Teaches you a new Engraving ability.\"" }
entries[220792] = { ["name"] = "Scroll of Spatial Mending", ["text"] = "Use: Close a targeted Fel portal. May draw unwanted attention from the other side.\nSell Price:" }
entries[220794] = { ["name"] = "Knight's Plate Hauberk", ["text"] = "Binds when picked up\nChest Plate\n557 Armor\n+15 Strength\n+17 Stamina\nDurability 135 / 135\nClasses: Warrior , Paladin\nRequires Level 50\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\nKnight-Lieutenant's Plate (0/6)\nKnight's Plate Hauberk\nKnight's Plate Leggings\nKnight-Lieutenant's Plate Helm\nKnight-Lieutenant's Plate Pauldrons\nSergeant Major's Plate Gauntlets\nSergeant Major's Plate Greaves\n(3) Set : +15 Stamina.\n(6) Set : +30 Attack Power.\nSell Price:" }
