entries[221336] = { ["name"] = "Schematic: Goblin Mining Helmet", ["text"] = "Binds when picked up\nRequires Engineering (205)\n\nUse:\n\nGoblin Mining Helmet\nBinds when picked up\nHead Mail\n190 Armor\n+15 Stamina\nDurability 60 / 60\nRequires Engineering (205)\nEquip: Mining +5.\nSell Price:\nRequires Mithril Bar (8), Citrine , Elemental Earth (4)" }
entries[221344] = { ["name"] = "Personal Spellbook", ["text"] = "Binds when picked up\nUnique\nHeld In Off-hand\nClasses: Mage\nEquip: Increases damage and healing done by magical spells and effects by up to 21.\n\nUse: Conjure 5 Comprehension Charms. (4 Hrs Cooldown)" }
