entries[221372] = { ["name"] = "Mangled Coin Purse", ["text"] = "\"The contents were likely damaged in combat.\"\nSell Price:" }
entries[221418] = { ["name"] = "Agamaggan's Roar", ["text"] = "Binds when picked up\nUnique\nUse: Catch the attention of a Delirious Ancient, drawing it into combat. (5 Sec Cooldown)" }
entries[221428] = { ["name"] = "Rune of Foul Play", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your bracers with the Unfair Advantage rune:\n\nWhenever you dodge or parry an attack you gain an Unfair Advantage, striking back for 100% of your main hand weapon's damage and gaining 1 combo point. This cannot occur more than once per second.\n\"Teaches you a new Engraving ability.\"" }
entries[221433] = { ["name"] = "Rune of Focus", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your helm with the Focused Attacks rune:\n\nYou gain 2 Energy every time you deal a melee or ranged critical strike.\n\"Teaches you a new Engraving ability.\"" }
entries[221445] = { ["name"] = "Rune of Focused Fire", ["text"] = "Binds when picked up\nClasses: Hunter\nEngrave your bracers with the Focus Fire rune:\n\nConsumes all applications of Frenzy from your pet, increasing your ranged attack speed by 3% and granting 4 Focus to your pet for each application of Frenzy consumed. Lasts 20 sec.\n\nYour pet gains Frenzy each time it uses a Basic Attack, increasing its melee attack speed by 6% for 10 sec, stacking up to 5 times.\n\"Teaches you a new Engraving ability.\"" }
entries[221461] = { ["name"] = "Rune of Carnage", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your bracers with the Carnage rune:\n\nYour abilities deal 15% increased damage to targets afflicted by one of your Bleed effects. Your Rupture also heals you for 40% of the damage it deals.\n\"Teaches you a new Engraving ability.\"" }
entries[221470] = { ["name"] = "Dream Emerald", ["text"] = "Sell Price:" }
entries[221471] = { ["name"] = "Emerald Wardens Chest", ["text"] = "Binds when picked up\n<Right Click to Open>" }
entries[221473] = { ["name"] = "Rune of the Watchman", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your helm with the Vigilance rune:\n\nFocus your protective gaze on a party or raid member, reducing their damage taken by 3% and transferring 10% of the threat they cause to you. In addition, each time they are hit by an attack your Taunt cooldown is refreshed. Lasts 30 min. This effect can only be on one target at a time.\n\"Teaches you a new Engraving ability.\"" }
entries[221480] = { ["name"] = "Spell Notes: Molten Armor", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your bracers with the Molten Armor rune:\n\nCauses [source value] Fire damage when hit, increases your spell critical strike chance by 5%, and reduces the chance you are critically hit by 5%. Only one type of Armor spell can be active on the Mage at any time. Lasts 30 min.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[221481] = { ["name"] = "Nihilist Epiphany", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your bracers with the Void Zone rune:\n\nSummons a void zone in the target area that deals [source value] Shadow damage to enemies that stand within it every second for 10 sec.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[221482] = { ["name"] = "Rune of Affliction", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your bracers with the Unstable Affliction rune:\n\nShadow energy slowly destroys the target, causing [source value] damage over 18 sec. In addition, if the Unstable Affliction is dispelled it will cause [source value] damage to the dispeller and silence them for 5 sec. Only one Unstable Affliction or Immolate per Warlock can be active on any one target.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[221483] = { ["name"] = "Rune of Burn", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your helm with the Burn rune:\n\nYour Flame Shock now strikes up to 5 targets, gains 6 sec increased duration, and deals 100% increased damage. In addition, while you have Flametongue Weapon imbued on your main hand equipped weapon, you gain increased spell damage equal to 150% of your Intellect.\n\"Teaches you a new Engraving ability.\"" }
entries[221487] = { ["name"] = "Spell Notes: Advanced Warding", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your helm with the Advanced Warding rune:\n\nYour Mana Shield, Frost Ward, and Fire Ward spells can now be cast on any friendly target and absorb 100% increased damage, with Mana Shield consuming 50% less mana per damage absorbed. Additionally, your Remove Lesser Curse is replaced with Remove Greater Curse.\n\nRemoves 1 Curse and 1 harmful Magic effect from a friendly target.\n\"Teaches you a new Engraving ability.\"" }
entries[221488] = { ["name"] = "Resolute Epiphany", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your helm with the Divine Aegis rune:\n\nCritical heals create a protective shield on the target, absorbing 30% of the amount healed. Lasts 12 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[221489] = { ["name"] = "Rune of Vengeance", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your helm with the Vengeance rune:\n\nWhen activated, this ability temporarily grants you a 30% increase to your maximum health for 20 sec. After the effect expires, the health is lost. Additionally, while in Metamorphosis, Vengeance causes your wings to slow your falling speed.\n\"Teaches you a new Engraving ability.\"" }
entries[221490] = { ["name"] = "Rune of Riptide", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nEngrave your bracers with the Riptide\nrune:\n\nHeals a friendly target for [source value] to [source value] and another [source value] over 15 sec. Your Chain Heals cast on that primary target within 15 sec will increase the amount of the Chain Heal by 25%. This spell also triggers Ancestral Awakening.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
entries[221491] = { ["name"] = "Shadowtooth Bag", ["text"] = "Binds when picked up\n\"Contains a random Darkmoon card.\"\n<Right Click to Open>" }
entries[221497] = { ["name"] = "Old Key", ["text"] = "Binds when picked up\nUnique\nClasses: Shaman\nUse: Opens Old Chest" }
entries[221498] = { ["name"] = "Sturdy Lunchbox", ["text"] = "Binds when picked up\n12 Slot Bag\nSell Price:" }
entries[221499] = { ["name"] = "Rune of the Felguard", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nEngrave your bracers with the Summon Felguard rune:\n\nSummons a Felguard under the command of the Warlock.\n\nThe Felguard benefits from all talents and effects that trigger from or benefit any of your other Demon minions.\n\"Teaches you a new Engraving ability.\"" }
entries[221510] = { ["name"] = "Rune of the Knight", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your bracers with the Sword and Board rune:\n\nWhen your Devastate and Revenge abilities deal damage they have a 30% chance of refreshing the cooldown of your Shield Slam ability and reducing its Rage cost by 100% for 5 sec.\n\"Teaches you a new Engraving ability.\"" }
entries[221511] = { ["name"] = "Rune of the Protector", ["text"] = "Binds when picked up\nUnique\nClasses: Warrior\nEngrave your helm with the Shield Mastery rune:\n\nIncreases all physical damage you deal by 10% while you have a shield equipped, and reduces the duration of all Disarm effects used against you by 50%. This does not stack with other Disarm duration reducing effects.\n\"Teaches you a new Engraving ability.\"" }
entries[221512] = { ["name"] = "Rune of Alacrity", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your bracers with the Cut to the Chase rune:\n\nYour Eviscerate and Envenom abilities refresh either your Slice and Dice or your Blade Dance duration to its 5 combo point maximum. If both are active, only the one with shortest remaining duration will be refreshed.\n\"Teaches you a new Engraving ability.\"" }
entries[221513] = { ["name"] = "Rune of Potency", ["text"] = "Binds when picked up\nUnique\nClasses: Rogue\nEngrave your helm with the Combat Potency rune:\n\nYou have a 20% chance to gain 15 Energy every time you deal melee damage with your off-hand weapon.\n\"Teaches you a new Engraving ability.\"" }
entries[221514] = { ["name"] = "Rune of Firepower", ["text"] = "Binds when picked up\nClasses: Hunter\nEngrave your helm with the Lock and Load rune:\n\nEach time you place a trap, your next Shot (except Scatter Shot) ability within 20 sec costs no mana and does not incur a cooldown.\n\"Teaches you a new Engraving ability.\"" }
entries[221515] = { ["name"] = "Rune of Detonation", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your bracers with the T.N.T. rune:\n\nIncreases the damage done by Explosive Shot and all your damaging traps by 10%. Additionally, the initial damage of Explosive Trap and the total periodic damage of your Immolation Trap are increased by 25% of your melee or ranged Attack Power.\n\"Teaches you a new Engraving ability.\"" }
entries[221516] = { ["name"] = "Rune of Primal Energy", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your bracers with the Improved Frenzied Regeneration rune:\n\nYour Frenzied Regeneration can now be used in all forms except Moonkin Form or while not shapeshifted. It now converts your active resource into health every second for 10 sec. Up to 10 Rage, 10 Energy, or 20% base Mana is converted per second into up to 10% health.\n\"Teaches you a new Engraving ability.\"" }
entries[221517] = { ["name"] = "Rune of Bloodshed", ["text"] = "Binds when picked up\nUnique\nClasses: Druid\nEngrave your helm with the Gore rune:\n\nStriking a target with Lacerate, Swipe, or Maul has a 15% chance to reset the cooldown on Mangle (Bear) and grant 10 Rage. Striking a target with Mangle (Cat) or Shred has a 15% chance to reset the cooldown on Tiger's Fury.\n\"Teaches you a new Engraving ability.\"" }
entries[221518] = { ["name"] = "Whisper", ["text"] = "Binds when picked up\nTwo-Hand Mace\n109 - 163 Damage Speed 2.60\n(52.31 damage per second)\n+20 Strength\n+12 Stamina\nDurability 100 / 100\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\nSell Price:" }
entries[221519] = { ["name"] = "Mannoroc Orb", ["text"] = "Quest Item\nUnique" }
entries[221544] = { ["name"] = "Stormcrow Egg", ["text"] = "Binds when picked up\nUnique" }
entries[221545] = { ["name"] = "Deciphered Warlock Notes", ["text"] = "Unique\nClasses: Priest , Shaman\nSell Price:" }
entries[221547] = { ["name"] = "Coded Warlock Notes", ["text"] = "Unique\nUse: A cipher is needed to understand the Warlock's notes. Who knows what magic it contains?\nSell Price:" }
entries[221549] = { ["name"] = "Wastewander Cipher", ["text"] = "\"Aids in the translation of documents written by Wastewander Bandits.\"" }
entries[221971] = { ["name"] = "Dreamsworn Horn", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Combine the collected reagents into a rune that will teach a new Engraving spell.\n\"A unique reagent that carries a fiery essence. A new rune may be crafted if you find other similar components.\"" }
entries[221972] = { ["name"] = "Dreampyre Fire", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Combine the collected reagents into a rune that will teach a new Engraving spell.\n\"A unique reagent that carries a fiery essence. A new rune may be crafted if you find other similar components.\"" }
entries[221973] = { ["name"] = "Dreamhunter Fang", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Combine the collected reagents into a rune that will teach a new Engraving spell.\n\"A unique reagent that carries a fiery essence. A new rune may be crafted if you find other similar components.\"" }
entries[221974] = { ["name"] = "Grimtotem Necklace", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Combine the collected reagents into a fragile staff that can end Undying Slumber.\n\"A necklace collected from a diseased Grimtotem Shaman.\"" }
entries[221975] = { ["name"] = "Broken Woodpaw Staff", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Combine the collected reagents into a fragile staff that can end Undying Slumber.\n\"Part of a staff collected from a diseased Woodpaw Mystic.\"" }
entries[221976] = { ["name"] = "Diseased Nature Staff", ["text"] = "Binds when picked up\nUnique\nClasses: Warlock\nUse: Awaken the current target from Undying Slumber.\n\"The staff is barely held together, but the ancient magic within may still be of use.\"" }
entries[221978] = { ["name"] = "Explorer's Soul", ["text"] = "Binds when picked up\nUnique\nSummon your Explorer Imp. Though it cannot fight, it can travel through portals to explore other worlds and bring back treasures.\n\"Learn to summon an Explorer Imp.\"" }
entries[221979] = { ["name"] = "Prophecy of Verdant Winter", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your helm with the Pain and Suffering rune:\n\nMind Blast, Mind Spike, and Mind Flay refresh the duration of your one of your Shadow Word: Pain, Void Plague, or Vampiric Touch abilities on the target back to its maximum duration. The ability with the shortest remaining duration will always be the one refreshed.\n\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth." }
entries[221980] = { ["name"] = "Prophecy of Awakened Chaos", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your helm with the Eye of the Void rune:\n\nCall an eye of the void to fight for you for 30 sec. The eye can cast a variety of curses on your target.\n\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth." }
entries[221981] = { ["name"] = "Prophecy of the Lost Tribe", ["text"] = "Binds when picked up\nUnique\nClasses: Priest\nEngrave your bracers with the Surge of Light rune:\n\nCritical spellcasts cause your next Smite or Flash Heal cast within 15 sec to be instant cast.\n\nUse: Focus on the Prophecy to learn a new spell. Requires a mind focused by meditating on two spiritual mysteries of Azeroth." }
entries[222962] = { ["name"] = "Hyjal's Wisdom", ["text"] = "Binds when picked up\nUnique\nUse: Learn a new Engraving ability." }
entries[223073] = { ["name"] = "Knight-Lieutenant's Mail Epaulets", ["text"] = "Binds when picked up\nShoulder Mail\n246 Armor\n+9 Strength\n+11 Stamina\n+5 Intellect\nDurability 70 / 70\nClasses: Hunter , Shaman\nRequires Level 50\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\nKnight-Lieutenant's Mail (0/6)\nKnight's Mail Armor\nSergeant Major's Mail Sabatons\nSergeant Major's Mail Gauntlets\nKnight-Lieutenant's Mail Helmet\nKnight's Mail Legplates\nKnight-Lieutenant's Mail Epaulets\n(3) Set : +15 Stamina.\n(6) Set : +30 Attack Power.\nSell Price:" }
entries[223074] = { ["name"] = "Knight's Mail Legplates", ["text"] = "Binds when picked up\nLegs Mail\n277 Armor\n+12 Strength\n+13 Stamina\n+12 Intellect\nDurability 90 / 90\nClasses: Hunter , Shaman\nRequires Level 50\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\nKnight-Lieutenant's Mail (0/6)\nKnight's Mail Armor\nSergeant Major's Mail Sabatons\nSergeant Major's Mail Gauntlets\nKnight-Lieutenant's Mail Helmet\nKnight's Mail Legplates\nKnight-Lieutenant's Mail Epaulets\n(3) Set : +15 Stamina.\n(6) Set : +30 Attack Power.\nSell Price:" }
entries[223075] = { ["name"] = "Knight-Lieutenant's Mail Helmet", ["text"] = "Binds when picked up\nHead Mail\n266 Armor\n+11 Strength\n+18 Stamina\n+7 Intellect\nDurability 70 / 70\nClasses: Hunter , Shaman\nRequires Level 50\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\nKnight-Lieutenant's Mail (0/6)\nKnight's Mail Armor\nSergeant Major's Mail Sabatons\nSergeant Major's Mail Gauntlets\nKnight-Lieutenant's Mail Helmet\nKnight's Mail Legplates\nKnight-Lieutenant's Mail Epaulets\n(3) Set : +15 Stamina.\n(6) Set : +30 Attack Power.\nSell Price:" }
entries[223076] = { ["name"] = "Sergeant Major's Mail Gauntlets", ["text"] = "Binds when picked up\nHands Mail\n191 Armor\n+8 Strength\n+10 Stamina\n+5 Intellect\nDurability 40 / 40\nClasses: Hunter , Shaman\nRequires Level 50\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\nKnight-Lieutenant's Mail (0/6)\nKnight's Mail Armor\nSergeant Major's Mail Sabatons\nSergeant Major's Mail Gauntlets\nKnight-Lieutenant's Mail Helmet\nKnight's Mail Legplates\nKnight-Lieutenant's Mail Epaulets\n(3) Set : +15 Stamina.\n(6) Set : +30 Attack Power.\nSell Price:" }
entries[223077] = { ["name"] = "Sergeant Major's Mail Sabatons", ["text"] = "Binds when picked up\nFeet Mail\n210 Armor\n+9 Strength\n+9 Stamina\n+8 Intellect\nDurability 60 / 60\nClasses: Hunter , Shaman\nRequires Level 50\nEquip: Minor increase to running and swimming speed.\n\nKnight-Lieutenant's Mail (0/6)\nKnight's Mail Armor\nSergeant Major's Mail Sabatons\nSergeant Major's Mail Gauntlets\nKnight-Lieutenant's Mail Helmet\nKnight's Mail Legplates\nKnight-Lieutenant's Mail Epaulets\n(3) Set : +15 Stamina.\n(6) Set : +30 Attack Power.\nSell Price:" }
entries[223078] = { ["name"] = "Knight's Mail Armor", ["text"] = "Binds when picked up\nChest Mail\n317 Armor\n+12 Strength\n+13 Stamina\n+12 Intellect\nDurability 120 / 120\nClasses: Hunter , Shaman\nRequires Level 50\nEquip: Improves your chance to get a critical strike with all spells and attacks by 1%.\n\nKnight-Lieutenant's Mail (0/6)\nKnight's Mail Armor\nSergeant Major's Mail Sabatons\nSergeant Major's Mail Gauntlets\nKnight-Lieutenant's Mail Helmet\nKnight's Mail Legplates\nKnight-Lieutenant's Mail Epaulets\n(3) Set : +15 Stamina.\n(6) Set : +30 Attack Power.\nSell Price:" }
entries[223147] = { ["name"] = "Spell Notes: Balefire Bolt", ["text"] = "Binds when picked up\nUnique\nClasses: Mage\nEngrave your bracers with the Balefire Bolt rune:\n\nUnleash a reality-distorting burst of raw magic at your enemy, dealing [source value] to [source value] Chimeric damage.\n\nIncreasing your Balefire Bolt and Pyroblast damage by 25%, decreasing your Spirit by 20%, and stacking up to 5 times for 30 sec. If your Spirit reaches 0, you die.\n\nThis spell will be checked against the lower of the target's Arcane, Fire, and Frost resists.\n\"Teaches you a new Engraving ability.\"", ["unresolvedValues"] = true }
