entries[226252] = { ["name"] = "Rune of the Guerrilla", ["text"] = "Binds when picked up\nUnique\nClasses: Hunter\nEngrave your cloak with the Hit and Run rune:\n\nYou gain 30% movement speed for 15 sec after using Raptor Strike.\n\nYour pet's damaging abilities send the target into a Rabid Frenzy, increasing their melee attack power by 91 but reducing armor by 640 for 2 min. Rabid enemies will not flee and will ignore Fear and Horror effects.\n\"Teaches you a new Engraving ability.\"" }
entries[226374] = { ["name"] = "Occult Poison I", ["text"] = "Classes: Rogue\nRequires Level 54\n\nUse: Coats a weapon with poison that lasts for 30 minutes. Each strike has a 30% chance of poisoning the enemy for 108 Nature damage over 12 sec and causing the enemy to take 4% increased Arcane, Fire, Frost, Nature, and Shadow damage. Stacks up to 5 times on a single target.\n\nOccult Poison counts as Deadly Poison and benefits from all talents and effects that trigger from or modify Deadly Poison. (Proc chance: 30%)\nSell Price:" }
entries[226404] = { ["name"] = "Tarnished Undermine Real", ["text"] = "Binds when picked up\nUnique (250)\n\"This Lost Isles currency is slowly being phased out of circulation, but it still enjoys a very favorable exchange rate throughout the Eastern Kingdoms and Kalimdor.\"" }
